insert into public.set_songs (id, set_id, text_id, unit, title, media_url, lines, position)
values ('00000000-0000-4000-8000-0000000004b1', '00000000-0000-4000-8000-000000000005', null, 4, 'The Architecture of Words',
        'assets/songs/the-architecture-of-words-words.mp4?v=20261119g', '[{"t": 11.9, "e": 14.65, "l": "Relentlessly! Relentlessly!"}, {"t": 14.65, "e": 17.75, "l": "Four strong beats when the work never stops!"}, {"t": 17.75, "e": 21.55, "l": "Showing determination from bottom to top!"}, {"t": 21.55, "e": 26.45, "l": "(That means you keep going, no matter what!)"}, {"t": 26.45, "e": 34.65, "l": "Starving! Starving! Only two!"}, {"t": 34.65, "e": 38.45, "l": "When your stomach is empty and food''s overdue!"}, {"t": 38.45, "e": 41.8, "l": "Feel very hungry, from morning till night!"}, {"t": 41.8, "e": 46.1, "l": "A big empty belly that craves for a bite!"}, {"t": 46.1, "e": 53.65, "l": "This is the way we take a word apart!"}, {"t": 53.65, "e": 59.9, "l": "Count every syllable right from the start!"}, {"t": 59.9, "e": 64.75, "l": "Slow and complex, but beautiful too!"}, {"t": 64.75, "e": 69.75, "l": "Learning the meaning in all that we do!"}, {"t": 69.75, "e": 74.7, "l": "Nervous! Nervous! Two small parts!"}, {"t": 74.7, "e": 77.6, "l": "The fluttery feeling that beats in our hearts!"}, {"t": 77.6, "e": 80.0, "l": "Shaky and worried, uneasy and shy!"}, {"t": 80.0, "e": 86.95, "l": "(Like watching a storm cloud roll in through the sky!)"}, {"t": 86.95, "e": 89.7, "l": "Ferocious! Ferocious! Count to three!"}, {"t": 89.7, "e": 92.8, "l": "As wild and as fierce as a tiger can be!"}, {"t": 92.8, "e": 96.1, "l": "Power and strength and a wild, loud roar!"}, {"t": 96.1, "e": 100.5, "l": "This is the way we take a word apart!"}, {"t": 100.5, "e": 107.8, "l": "Count every syllable right from the start!"}, {"t": 107.8, "e": 113.65, "l": "Slow and complex, but beautiful too!"}, {"t": 113.65, "e": 119.15, "l": "Learning the meaning in all that we do!"}, {"t": 119.15, "e": 120.95, "l": "Deliberately! Count up five!"}, {"t": 120.95, "e": 122.9, "l": "Done on purpose to feel so alive!"}, {"t": 122.9, "e": 124.45, "l": "Not by mistake, but by choice, you can see!"}, {"t": 124.45, "e": 125.9, "l": "(Carefully planned, just for you and for me!)"}, {"t": 125.9, "e": 128.4, "l": "And last comes the Brilliant! Brilliant! Three!"}, {"t": 128.4, "e": 131.5, "l": "Like a bright shining light for the whole world to see!"}, {"t": 131.5, "e": 137.8, "l": "This is the way we take a word apart!"}, {"t": 137.8, "e": 142.65, "l": "Count every syllable right from the start!"}, {"t": 142.65, "e": 148.8, "l": "Slow and complex, but beautiful too!"}, {"t": 148.8, "e": 153.85, "l": "Learning the meaning in all that we do!"}, {"t": 153.85, "e": 158.75, "l": "Count them up... know them well..."}, {"t": 158.75, "e": 161.3, "l": "Every word... every syllable we can spell..."}, {"t": 161.3, "e": 168.9, "l": "Relentlessly... Starving... Nervous... Ferocious..."}, {"t": 168.9, "e": 174.6, "l": "Deliberately... Brilliant... all for you... and me..."}]'::jsonb, 1)
on conflict (id) do update set title = excluded.title, media_url = excluded.media_url, lines = excluded.lines, unit = excluded.unit;
